window.__finlexDocLoaded(10177,{"id":10177,"articles":[{"id":1000739,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Limits annual deductible business interest expense to business interest income plus 30% of Adjusted Taxable Income (ATI), with disallowed interest carried forward indefinitely.","seq":0},{"id":1000740,"no":"IRC §163(j)","heading":"30% ATI Cap, Carryforward & Small Business Exemption","text":"• General Limit: Deductible business interest capped at (1) Business Interest Income + (2) 30% of Adjusted Taxable Income (ATI) + (3) Floor plan financing interest.\n• ATI Base: Shifted from EBITDA-like base (2018–2021) to EBIT-like base (starting 2022, after depreciation & amortization), subject to ongoing US statutory modifications.\n• Indefinite Carryforward: Disallowed interest carries forward indefinitely (creating a Deferred Tax Asset evaluated for valuation allowance under ASC 740).","seq":1},{"id":1000741,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Comparable to OECD BEPS Action 4 (30% EBITDA interest barrier) and China's thin-capitalization debt-to-equity ratio rule (2:1 / 5:1 under Enterprise Income Tax Law Art. 46).","seq":2},{"id":1000742,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (Office of the Law Revision Counsel (U.S. Code)): https://uscode.house.gov/\nStatus: in_force.","seq":3}]});
